    setStartDate(date);
    if (date) {
      setStartDateUtcFormated(getUTCDifrrenceDateTime(date));
    }
    setStartDateFormated(UtilityClass.getFormatedDateWithoutTime(date));
  }, []);

  const handleEndDateChange = (date) => {
