import { useState } from "react";

const useGoogleMapGeocodeGetLatLng = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const getLatLng = (address) => {
    setIsLoading(true);
    return new Promise((resolve, reject) => {
      const geocoder = new window.google.maps.Geocoder();
      geocoder.geocode({ address: address }, (results, status) => {
        setIsLoading(false);
        if (status === "OK") {
          const lat = results[0].geometry.location.lat();
          const lng = results[0].geometry.location.lng();
          resolve({ lat, lng });
        } else {
          setError(new Error("Error getting latitude and longitude"));
          reject(new Error("Error getting latitude and longitude"));
        }
      });
    });
  };

  return { getLatLng, isLoading, error };
};

export default useGoogleMapGeocodeGetLatLng;

import { useState, useEffect } from "react";
import { CheckMobileNoDuplicate } from "../../api/AxiosInterceptors";

/**
 * Custom hook to validate and check duplicate mobile number orders dynamically
 * @param {string} mobileNo - The mobile number to check
 * @param {number} minLength - The minimum length to trigger API lookup (default 8)
 * @param {number} delay - Debounce delay in milliseconds (default 600)
 */
export default function useOrderMobileDuplicateCheck(mobileNo, minLength = 8, delay = 600) {
  const [warningState, setWarningState] = useState({
    isDuplicate: false,
    orderNo: "",
    daysAgo: 0,
  });

  useEffect(() => {
    if (!mobileNo || mobileNo.length < minLength) {
      setWarningState({ isDuplicate: false, orderNo: "", daysAgo: 0 });
      return;
    }

    const timer = setTimeout(async () => {
      try {
        const res = await CheckMobileNoDuplicate(mobileNo);
        if (res?.data?.isSuccess && res.data.result?.isDuplicate) {
          setWarningState({
            isDuplicate: true,
            orderNo: res.data.result.orderNo,
            daysAgo: res.data.result.daysAgo,
          });
        } else {
          setWarningState({ isDuplicate: false, orderNo: "", daysAgo: 0 });
        }
      } catch (err) {
        console.error("Error checking mobile duplicate:", err);
      }
    }, delay);

    return () => clearTimeout(timer);
  }, [mobileNo, minLength, delay]);

  return warningState;
}

import { useState } from "react";

const useOpenStreetmapGetLatLng = () => {
  const [isLoadingCoordinates, setIsLoadingCoordinates] = useState({});
  const [error, setError] = useState(null);

  const getAddressCoordinates = async (address) => {
    setIsLoadingCoordinates(true);
    // setIsLoadingCoordinates({ [row.orderNo]: true });
    if (address) {
      setError(null);

      const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(
        address
      )}`;

      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error("Network response was not ok");
        }
        const data = await response.json();
        console.log("Data from API:", data); // Log data from the API
        if (data && data.length > 0) {
          const firstResult = data[0];
          console.log("First result:", firstResult); // Log the first result
          const latitude = parseFloat(firstResult.lat);
          const longitude = parseFloat(firstResult.lon);
          console.log("latitude:", latitude);
          console.log("longitude", longitude);
          setIsLoadingCoordinates(false);
          return { lat: latitude, lng: longitude };
        } else {
          throw new Error("No results found");
        }
      } catch (error) {
        setIsLoadingCoordinates(false);
        setError(`Error fetching address coordinates: ${error.message}`);
      }
    }
  };

  return { getAddressCoordinates, isLoadingCoordinates, error };
};

