            {drawnCoords.map((pt, idx) => (
              <Marker
                key={idx}
                position={pt}
                icon={{
                  path: window.google?.maps?.SymbolPath?.CIRCLE || 0,
                  scale: 6,
                  fillColor: "#2e7d32",
                  fillOpacity: 1,
                  strokeColor: "#ffffff",
                  strokeWeight: 2,
                }}
              />
            ))}
          </>
        )}

