function CarrierSettlementPage(props) {
  const [allCarrierPaymentSettlements, setAllCarrierPaymentSettlements] =
    useState([]);
  const [isLoading, setIsLoading] = useState(false);

  let getAllCarrierPaymentSettlements = async () => {
    setIsLoading(true);
    let res = await GetAllCarrierPaymentSettlements({
      filterModel: {
        createdFrom: null,
        createdTo: null,
        start: 0,
        length: 10000,
        search: "",
        sortDir: "desc",
        sortCol: 0,
      },
    });
    setIsLoading(false);
    if (res.data.result !== null)
      setAllCarrierPaymentSettlements(res.data.result.list);
  };

  useEffect(() => {
    getAllCarrierPaymentSettlements();
  }, []);
  const LanguageReducer = useSelector((state) => state.LanguageReducer);
  return (
    <Box sx={styleSheet.pageRoot}>
      <div style={{ padding: "10px" }}>
        {" "}
        <CarrierSettlementList
          loading={isLoading}
          getAllCarrierPaymentSettlements={getAllCarrierPaymentSettlements}
          allCarrierPaymentSettlements={allCarrierPaymentSettlements}
        />
      </div>
    </Box>
  );
}
export default CarrierSettlementPage;

import { Box, Typography } from "@mui/material";
import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { DataGridPro } from "@mui/x-data-grid-pro";
import { styleSheet } from "../../../assets/styles/style";
import { 
  usePagination,
  centerColumn,
  navbarHeight,
  useClientSubscriptionReducer,
  useGetWindowHeight,
  getElementByInnerHTML,
} from "../../../utilities/helpers/Helpers";

function ContactsList(props) {
  const { loading, allContacts, onContactClick } = props;
  const LanguageReducer = useSelector((state) => state.LanguageReducer);

  const clientSubscriptionData = useClientSubscriptionReducer();
  const { height: windowHeight } = useGetWindowHeight(clientSubscriptionData);
  const [flag, setFlag] = useState(false);
  const [showContent, setShowContent] = useState(false);

  useEffect(() => {
    setFlag((prev) => !prev);
  }, [loading]);

  useEffect(() => {
    const selectedElement = getElementByInnerHTML("MUI X Missing license key");
    if (selectedElement) {
      setShowContent(true);
      selectedElement.style.display = "none";
    }
  }, [flag]);

  const columns = [
    {
      field: "Mobile",
      headerName: <Box sx={{ fontWeight: "600" }}>Mobile</Box>,
      minWidth: 150,
      flex: 1,
      renderCell: (params) => (
        <Box 
          sx={{ cursor: "pointer", color: "blue", textDecoration: "underline" }}
          onClick={() => onContactClick(params.row.Mobile)}
        >
          <span style={styleSheet.tableText}>{params.row.Mobile}</span>
        </Box>
      ),
    },
    {
      field: "CustomerName",
      headerName: <Box sx={{ fontWeight: "600" }}>Name</Box>,
      minWidth: 200,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.CustomerName || params.row.Name || "-"}</span>
      ),
    },
    {
      field: "TotalOrders",
      headerName: <Box sx={{ fontWeight: "600" }}>Total Orders</Box>,
      minWidth: 150,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.TotalOrders}</span>
      ),
    },
  ];

  const { currentPage, pageSize, handlePageChange, handlePageSizeChange } =
    usePagination(0, 10);

  const rows = allContacts?.list ?? [];

  const calculatedHeight = windowHeight - navbarHeight - 67;

  return (
    <Box
      sx={{
        ...styleSheet.allOrderTable,
        height: calculatedHeight,
        "& .MuiDataGrid-main div": {
          opacity: showContent ? 1 : 0,
        },
      }}
    >
      <DataGridPro
        loading={loading}
        headerHeight={40}
        sx={{
          fontFamily: "'Lato Regular', 'Inter Regular', 'Arial' !important",
          fontSize: "12px",
          fontWeight: "500",
        }}
        rows={rows}
        getRowId={(row) => row.Mobile}
        columns={columns}
        disableRowSelectionOnClick
        checkboxSelection
        pagination
        page={currentPage}
        pageSize={pageSize}
        rowsPerPageOptions={[5, 10, 15, 25]}
        paginationMode="client"
        onPageChange={handlePageChange}
        onPageSizeChange={handlePageSizeChange}
      />
    </Box>
  );
}

export default ContactsList;

import {
  Box,
} from "@mui/material";

import React, { useEffect, useState } from "react";
import { useSelector } from "react-redux";
import { Route, Routes } from "react-router-dom";

import { GetLeadContacts } from "../../api/AxiosInterceptors";
import { styleSheet } from "../../assets/styles/style";
import { warningNotification } from "../../utilities/toast";

import SearchInputAutoCompleteMultiple from "../../.reUseableComponents/TextField/SearchInputAutoCompleteMultiple";
import ContactOrdersModal from "../../components/modals/leadsModals/ContactOrdersModal";

import ContactsList from "./contactsList";
import DataGridTabs from "../../.reUseableComponents/DataGridTabs/DataGridTabs";

const MAX_TAGS = 200;

function Contacts(props) {
  const [inputFields, setInputFields] = useState([]);
  const [allContacts, setAllContacts] = useState([]);
  const [isContactsLoading, setIsContactsLoading] = useState(false);
  const [openContactModal, setOpenContactModal] = useState(false);
  const [selectedContactMobile, setSelectedContactMobile] = useState(null);

  const LanguageReducer = useSelector((state) => state.LanguageReducer);

  const getAllContacts = async () => {
    setIsContactsLoading(true);
    try {
      const params = {
        Start: 0,
        Length: 1000,
        Search: inputFields.join(),
      };
      const res = await GetLeadContacts(params);
      if (res?.data?.result) {
        setAllContacts(res.data.result);
      }
    } catch (e) {
      console.error("Error fetching contacts:", e);
    } finally {
      setIsContactsLoading(false);
    }
  };

  useEffect(() => {
    getAllContacts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    let timeoutId;
    if (inputFields.length > 0) {
      timeoutId = setTimeout(() => {
        getAllContacts();
      }, 800);
    } else {
      getAllContacts();
    }
    return () => clearTimeout(timeoutId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inputFields]);

  return (
    <Box sx={styleSheet.pageRoot}>
      <div style={{ padding: "10px" }}>
        <Box sx={{ mb: 1 }}>
          <Box
            sx={{ display: "flex", alignItems: "center", gap: 1 }}
          >
            <Box flexGrow={1}>
              <SearchInputAutoCompleteMultiple
                onChange={(e, value) => {
                  if (value.length <= MAX_TAGS) {
                    setInputFields(value.slice(0, MAX_TAGS));
                  } else {
                    warningNotification(
                      LanguageReducer?.languageType?.MAXMIUM_NUMBER_REACHED ||
                        "Maximum tag limit reached"
                    );
                  }
                }}
                inputFields={inputFields}
                MAX_TAGS={MAX_TAGS}
              />
            </Box>
          </Box>
        </Box>

        <DataGridTabs
          handleTabChange={() => {}}
          tabData={[
            {
              label: "Contacts",
              route: "/contacts",
            },
          ]}
          actionBtnMenuData={null}
          otherBtns={null}
          filterBtn={null}
        />

        <Routes>
          <Route 
            path="/" 
            element={
              <ContactsList 
                loading={isContactsLoading} 
                allContacts={allContacts} 
                onContactClick={(mobile) => {
                  setSelectedContactMobile(mobile);
                  setOpenContactModal(true);
                }} 
              />
            } 
          />
        </Routes>

{
              label: "Contacts",
              route: "/contacts",
            },
          ]}
          actionBtnMenuData={null}
          otherBtns={null}
          filterBtn={null}
        />

        <Routes>
          <Route 
            path="/" 
            element={
              <ContactsList 
                loading={isContactsLoading} 
                allContacts={allContacts} 
                onContactClick={(mobile) => {
                  setSelectedContactMobile(mobile);
                  setOpenContactModal(true);
                }} 
              />
            } 
          />
        </Routes>
      </div>

      <ContactOrdersModal 
        open={openContactModal} 
        onClose={() => setOpenContactModal(false)} 
        mobileNumber={selectedContactMobile} 
      />
    </Box>
  );
}

