      minWidth: 150,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.productName}</span>
      ),
    },
    {
      field: "CustomerName",
      headerName: <Box sx={{ fontWeight: "600" }}>Customer Name</Box>,
      minWidth: 150,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.customerName}</span>
      ),
    },
    {
      field: "Address",
      headerName: <Box sx={{ fontWeight: "600" }}>Address</Box>,
      minWidth: 200,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.address}</span>
      ),
    },
    {
      field: "Amount",
      headerName: <Box sx={{ fontWeight: "600" }}>Amount</Box>,
      minWidth: 120,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.amount}</span>
      ),
    },
  ];

  return (
    <>
      <Box
        sx={{
          ...styleSheet.allOrderTable,
          height: calculatedHeight,
        }}
      >
        <DataGrid
          loading={loading}
          rowHeight={40}
          headerHeight={40}
          sx={{
            fontFamily: "'Lato Regular', 'Inter Regular', 'Arial' !important",
            fontSize: "12px",
            fontWeight: "500",

headerName: <Box sx={{ fontWeight: "600" }}>Amount</Box>,
      minWidth: 120,
      flex: 1,
      renderCell: (params) => (
        <span style={styleSheet.tableText}>{params.row.amount}</span>
      ),
    },
  ];

  return (
    <>
      <Box
        sx={{
          ...styleSheet.allOrderTable,
          height: calculatedHeight,
        }}
      >
        <DataGrid
          loading={loading}
          rowHeight={40}
          headerHeight={40}
          sx={{
            fontFamily: "'Lato Regular', 'Inter Regular', 'Arial' !important",
            fontSize: "12px",
            fontWeight: "500",
          }}
          getRowId={(row) => row.rowNum}
          rows={uploadLeadsData || []}
          columns={columns}
          disableSelectionOnClick
          pagination
          page={currentPage}
          pageSize={pageSize}
          rowsPerPageOptions={[5, 10, 25]}
          paginationMode="client"
          onPageChange={handlePageChange}
