const getPolygonCentroid = (coords) => {
  if (!coords || coords.length === 0) return { lat: 0, lng: 0 };
  let latSum = 0;
  let lngSum = 0;
  coords.forEach((pt) => {
    latSum += pt.lat;
    lngSum += pt.lng;
  });
  return { lat: latSum / coords.length, lng: lngSum / coords.length };
};

