      const { response } = await fetchMethod(() => GetWallet());
      if (response.isSuccess) {
        setAllwallets(response.result);
      }
    } catch (error) {
      console.error("Error fetching client return reasons:", error);
    }
    setLoading(false);
  };

  const handleFilter = () => {
    getAllPayouts();
  };

