                        optionLabel={EnumOptions.SELECT_STATION.LABEL}
                        optionValue={EnumOptions.SELECT_STATION.VALUE}
                        getOptionLabel={(option) => option?.sname}
                        onChange={(e, val) => {
                          setSelectedStation(val);
                        }}
                      />
                    </Grid>
                  </Grid>

                  <Grid
                    item
                    xl={2}
