  const sampleProductLabel = useMemo(() => {
    const selected = (formData.products || []).find(
      (p) => p.Selected && p.SKU && !/^[0-9a-fA-F-]{20,}$/.test(p.SKU)
    );
    return (
      selected?.SKU ||
      selected?.VariantSKU ||
      selected?.Title ||
      selected?.VariantName ||
      "TS-BLK-M"
    );
  }, [formData.products]);

