          fetchPolicies(activeFilters);
        } else {
          errorNotification(res?.data?.message || "Failed to delete policy");
        }
      })
      .catch((err) => {
        console.error(err);
        errorNotification("Error deleting policy");
      });
  };

setSelectedPolicyForEdit(null);
