function UpgradeCancelEndTrialConfirmationModal(props) {
  let {
    open,
    setOpen = () => {},
    onClose = () => {},
    loading = false,
    onConfirm = () => {},
    buttonColor = Colors.primary,
    heading = "",
    message = "",
    messageDetails = "",
    buttonText = "Deactivate",
    hasFeedback,
  } = props;
  const initialFeedbackFields = {
    selectedReason: null,
    comment: "",
  };
  const [feedback, setFeedback] = useState(initialFeedbackFields);
  const handleClose = () => {
    onClose();
    setFeedback(initialFeedbackFields);
    setOpen(false);
  };
  return (
    <ModalComponent
      open={open}
      onClose={handleClose}
      maxWidth="sm"
      actionBtn={
        <ModalButtonComponent
          title={buttonText}
          loading={loading}
          bg={buttonColor}
          onClick={() => {
            if (!hasFeedback) {
              onConfirm(feedback);
              return;
            }
            if (hasFeedback && feedback.selectedReason && feedback.comment) {
              onConfirm(feedback);
              return;
            }
