const ZoneModal = ({
  open,
  onClose,
  onSave,
  cities = [],
  initialData = null,
  isEdit = false,
}) => {
  const LanguageReducer = useSelector((state) => state.LanguageReducer);
  const [zoneName, setZoneName] = useState("");
  const [cityId, setCityId] = useState("");
  const [loading, setLoading] = useState(false);

  const cityOptions = useMemo(() => {
    return (cities || []).map((city) => {
      const idVal =
        city.cityID ??
        city.CityID ??
        city.cityId ??
        city.CityId ??
        city.id ??
        city.Id ??
        city.value;
      const labelVal =
        city.name ||
        city.Name ||
        city.cityName ||
        city.CityName ||
        city.text ||
        city.label ||
        "Unnamed City";
      return {
        label: labelVal,
        value: idVal !== undefined && idVal !== null ? String(idVal) : "",
      };
    });
  }, [cities]);

  useEffect(() => {
    if (initialData) {
      setZoneName(initialData.name || initialData.Name || "");
      const rawCityId =
        initialData.cityID ??
        initialData.CityID ??
        initialData.cityId ??
        initialData.CityId ??
        "";
      setCityId(
        rawCityId !== undefined && rawCityId !== null ? String(rawCityId) : "",
      );
    } else {
      setZoneName("");
      setCityId("");
    }
  }, [initialData, open]);

