const DEFAULT_CENTER = { lat: 25.276987, lng: 55.296249 }; // UAE default coordinates

const getPolygonCentroid = (coords) => {
  if (!coords || coords.length === 0) return DEFAULT_CENTER;
  let latSum = 0;
  let lngSum = 0;
  coords.forEach((pt) => {
    latSum += pt.lat;
    lngSum += pt.lng;
  });
  return {
    lat: latSum / coords.length,
    lng: lngSum / coords.length,
  };
};

