        );
      },
    },
    {
      field: "Carrier",
      headerName: <DataGridHeaderBox title={"Carrier"} />,
      minWidth: 300,
      flex: 1,
      renderCell: ({ row }) => {
        return (
          <>
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              {row?.carrierName && (
                <Avatar
                  variant="rounded"
                  src={row?.carrierImage}
                  alt={row?.carrierName}
                  sx={{
                    width: 35,
                    height: 35,
                    bgcolor: "#fff",
                    borderRadius: "8px",

...styleSheet.allOrderTable,
          height: calculatedHeight,
        }}
      >
        <DataGrid
          loading={loading}
          rowHeight={50}
          headerHeight={40}
          sx={{
            fontFamily: "'Lato Regular', 'Inter Regular', 'Arial' !important",
            fontSize: "12px",
            fontWeight: "500",
          }}
          getRowId={(row) => row.activeCarrierPickupLocationId}
          rows={pickUpLocationData || []}
          columns={column}
          disableSelectionOnClick
          pagination
          page={currentPage}
          pageSize={pageSize}
          rowsPerPageOptions={[5, 10, 15, 25]}
          paginationMode="client"
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      </Box>
      {openDelete && (
        <DeleteConfirmationModal
          open={openDelete}
          setOpen={setOpenDelete}
          loading={deleteLoading}
          handleDelete={handleDeletePickUpLocation}
          heading={"Confirm Deletion of Pickup Location"}
