export function CopyButton({
  onClick,
  label = "Copy",
  width = "90px",
  height = "29px",
  marginBottom,
  padding = "14px",
}) {
  const [copied, setCopied] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleClick = async (e) => {
    if (loading) return;

    setLoading(true);
    const result = await onClick(e);
    setLoading(false);

    if (result) {
      setCopied(true);
      setTimeout(() => setCopied(false), 5000);
    }
  };

  return (
    <LoadingButton
      loading={loading}
      onClick={handleClick}
      sx={{
        width,
        minWidth: width,
        height,
        background: copied
          ? "green"
          : "var(--primary-color)  !important",
