// amountFormat
export const amountFormat = (amount) => {
  if (amount) {
    amount = eval(amount);
    return amount?.toFixed(2).replace(/(\d)(?=(\d{3})+(?!\d))/g, "$1,");
  } else {
    return "0.00";
  }
};

