      if (data.address) {
        setAutocomplete(data);
      } else {
        setError("Address not found");
      }
    } catch (error) {
      setError("Error fetching geolocation data");
      console.error("Error fetching geolocation data:", error);
    }
  };

  return { autocomplete, error, handleValues };
};

