import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import SelectComponent from "../../.reUseableComponents/TextField/SelectComponent";
import { setCountriesList, updateSelectedCountry } from "../../redux/country";
import { setThisKeyCookie, removeThisKeyCookie, isShowCountryInTabbarFlag } from "../cookies";
import { EnumCookieKeys, EnumOptions } from "../enum";
import { handleGetAllCountries } from "./addressSchema";

export const CountrySchema = ({
  name = "country",
  value,
  onChange,
  height = 37,
  placeholder = "Select Country",
  disabled = false,
  required = false,
  addPleaseSelectOptionOnClear = true,
  ...restProps
}) => {
  const dispatch = useDispatch();
  const isShowCountryInTabbar = isShowCountryInTabbarFlag();
  const reduxSelectedCountry = useSelector(
    (state) => state.CountryReducer?.selectedCountry,
  );
  const reduxCountries = useSelector(
    (state) => state.CountryReducer?.countries,
  );

  const [countriesList, setCountriesListState] = useState(reduxCountries || []);
  const [loading, setLoading] = useState(false);

  // Fetch countries if not available in Redux
  useEffect(() => {
    let isMounted = true;
    const fetchCountries = async () => {
      if (!reduxCountries || reduxCountries.length === 0) {
        setLoading(true);
        const data = await handleGetAllCountries();
        if (isMounted) {
          setCountriesListState(data || []);
          dispatch(setCountriesList(data || []));
          setLoading(false);
        }
      } else {
        setCountriesListState(reduxCountries);
      }
    };
    fetchCountries();
    return () => {
      isMounted = false;
    };
  }, [reduxCountries, dispatch]);

  // Determine current selected country object
  const matchedReduxCountry =
    countriesList.find(
      (c) =>
        c[EnumOptions.COUNTRY.VALUE] ===
        reduxSelectedCountry?.[EnumOptions.COUNTRY.VALUE],
    ) || reduxSelectedCountry;

  const selectedValue =
    value !== undefined && value !== null
      ? value
      : isShowCountryInTabbar
        ? matchedReduxCountry
        : null;

  // Whenever Redux selected country changes, inform parent via `onChange` (Global mode only)
  useEffect(() => {
    if (isShowCountryInTabbar && onChange) {
      onChange(name, matchedReduxCountry || null);
    }
  }, [reduxSelectedCountry, countriesList, isShowCountryInTabbar]);

  const handleChange = (fieldName, newValue, triggeredAction) => {
    const selectedObj =
      newValue && newValue[EnumOptions.COUNTRY.VALUE] !== 0 ? newValue : null;

    if (isShowCountryInTabbar) {
      dispatch(updateSelectedCountry(selectedObj));
      if (selectedObj?.[EnumOptions.COUNTRY.VALUE]) {
        setThisKeyCookie(
          EnumCookieKeys.COUNTRY_ID,
          selectedObj[EnumOptions.COUNTRY.VALUE],
        );
      } else {
        removeThisKeyCookie(EnumCookieKeys.COUNTRY_ID);
      }
    }

    if (onChange) {
      onChange(fieldName || name, selectedObj, triggeredAction);
    }
  };

  return (
    <SelectComponent
      name={name}
      options={countriesList}
      value={selectedValue}
      onChange={handleChange}
      height={height}
      isLoading={loading}
      disabled={disabled}
      required={required}
      placeholder={placeholder}
      optionLabel={EnumOptions.COUNTRY.LABEL}
      optionValue={EnumOptions.COUNTRY.VALUE}
      addPleaseSelectOptionOnClear={addPleaseSelectOptionOnClear}
      {...restProps}
    />
  );
};

export default CountrySchema;

import axios from "axios";
import React, { useEffect, useState } from "react";
const useCurrentCountryLocation = () => {
  const [data, setData] = useState(null);
  const [location, setLocation] = useState({ latitude: null, longitude: null });
  const [error, setError] = useState(null);

  const getCountryName = async (latitude, longitude) => {
    const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`;
    try {
      const response = await axios.get(url);
      const data = response.data;

      if (data) {
        setData(data.address);
      } else {
        setError("Country not found");
      }
    } catch (err) {
      console.error("Error fetching country:", err);
      setError("Failed to fetch country data");
    }
  };

  const handleSuccess = (position) => {
    const latitude = position.coords.latitude;
    const longitude = position.coords.longitude;
    setLocation({ latitude, longitude });
    getCountryName(latitude, longitude);
  };

  const handleError = (error) => {
    console.log("Geolocation error:", error);
    setError("Unable to retrieve your location");
  };

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(handleSuccess, handleError);
    } else {
      setError("Geolocation not supported");
    }
  }, []);

  return { data, location, error };
};

export default useCurrentCountryLocation;

import React from "react";
import { getMenuIcon } from "../../components/sideNavBar/icons";
import { handleGetDraftOrdersCount } from "../../components/authRoutes";

/**
 * Transforms GetAllClientMenuByRoleId API response into navBarMenu format for PrivateRoutes and SideNavBar.
 * Merges API menuOtherRoutes with static navBarMenu's otherRoutes to maintain full route coverage.
 */
export const transformApiMenuToNavBarMenu = (
  apiMenuItems = [],
  LanguageReducer,
  staticNavBarMenu = []
) => {
  if (!Array.isArray(apiMenuItems) || apiMenuItems.length === 0) {
    return [];
  }

  // 1. Only include main menus where hasPermission !== false
  const allowedMainMenus = apiMenuItems.filter(
    (menu) => menu.hasPermission === true || menu.hasPermission !== false
  );

  // 2. Sort top-level menus by displayOrder
  const sortedMenus = [...allowedMainMenus].sort(
    (a, b) => (a.displayOrder || 0) - (b.displayOrder || 0)
  );

  return sortedMenus.map((menu) => {
    const rawItems = menu.menuItems || [];

    // 3. Only include sub-items where hasPermission !== false
    const validSubItems = rawItems.filter(
      (sub) => sub.hasPermission === true || sub.hasPermission !== false
    );

    const sortedSubItems = [...validSubItems].sort(
      (a, b) => (a.displayOrder || 0) - (b.displayOrder || 0)
    );

    // Set isCollapse = true whenever allowed sub-items exist
    const isCollapse = sortedSubItems.length > 0;

    const subTabData = sortedSubItems.map((sub) => ({
      menuItemId: sub.menuItemId,
      sideTitle: sub.menuItemName || sub.menuItemTabBarTitle || sub.tabBarTitle,
      topTitle: sub.menuItemTabBarTitle || sub.menuItemName || sub.tabBarTitle,
      path: sub.routePath,
      displayOrder: sub.displayOrder,
      hasPermission: sub.hasPermission,
      hasBadge: sub.routePath === "/draft-order-dashboard",
      handleShowBadge:
        sub.routePath === "/draft-order-dashboard"
          ? handleGetDraftOrdersCount
          : null,
    }));

    // Find matching static menu to fetch default subTabData and otherRoutes
    const matchedStaticMenu = (staticNavBarMenu || []).find(
      (st) => st?.tabData?.path === menu.routePath
    );

    // Merge static subTabData if not present in API items (e.g. newly created routes like /sync-policies)
    if (matchedStaticMenu?.subTabData) {
      matchedStaticMenu.subTabData.forEach((stSub) => {
        if (
          stSub?.path &&
          !subTabData.some((s) => s.path === stSub.path)
        ) {
          subTabData.push(stSub);
        }
      });
    }

    // Map API menuOtherRoutes
    const apiOtherRoutes = (menu.menuOtherRoutes || []).map((other) => ({
      topTitle: other.tabBarTitle || other.topTitle || other.menuItemName,
      path: other.routePath || other.path,
    }));

    // Merge API otherRoutes with static otherRoutes (avoiding duplicates)
    const combinedOtherRoutes = [...apiOtherRoutes];

    if (matchedStaticMenu?.otherRoutes) {
      matchedStaticMenu.otherRoutes.forEach((stOther) => {
        if (
          stOther?.path &&
          !combinedOtherRoutes.some((o) => o.path === stOther.path)
        ) {
          combinedOtherRoutes.push(stOther);
        }
      });
    }

    return {
      menuId: menu.menuId,
      displayOrder: menu.displayOrder,
      hasPermission: menu.hasPermission,
      isCollapse: isCollapse,
      tabData: {
        sideTitle: menu.menuName || menu.menuTabBarTitle || menu.tabBarTitle,
        topTitle: menu.menuTabBarTitle || menu.menuName || menu.tabBarTitle,
        path: menu.routePath,
      },
      subTabData: subTabData,
      otherRoutes: combinedOtherRoutes,
      icon: getMenuIcon(menu.menuIcon || menu.menuName),
    };
  });
};

import { useDispatch, useSelector } from "react-redux";
import { handleDispatIsApiFilterModelFlag } from "./Helpers";
import { useState, useEffect } from "react";
import { Box, Pagination, Typography } from "@mui/material";
import { isShowCountryInTabbarFlag } from "../cookies";

export const PaginationComponent = ({
  color = "primary",
  dataCount = 0,
  paginationMethodUrl = "",
  paginationChangeMethod = async () => {},
  defaultRowsPerPage,
  setLoading = () => {},
  name,
  sx,
  currentPage,
}) => {
  const dispatch = useDispatch();
  const reduxSelectedCountry = useSelector(
    (state) => state.CountryReducer?.selectedCountry
  );
  const [page, setPage] = useState(1);

  useEffect(() => {
    if (!isShowCountryInTabbarFlag()) return;
    if (paginationMethodUrl) {
      handleDispatIsApiFilterModelFlag(dispatch, {
        apiName: paginationMethodUrl,
        page: 0,
        pageSize: defaultRowsPerPage,
      });
    }
    setPage(1);
  }, [reduxSelectedCountry]);

  useEffect(() => {
    if (currentPage !== undefined) {
      setPage(currentPage + 1);
    }
  }, [currentPage]);

  const handleChange = async (event, newPage) => {
    setPage(newPage);
    setLoading(true);
    handleDispatIsApiFilterModelFlag(dispatch, {
      apiName: paginationMethodUrl,
      page: newPage - 1,
      pageSize: defaultRowsPerPage,
    });

    await paginationChangeMethod(newPage - 1, defaultRowsPerPage);
    setLoading(false);
  };

  const count = Math.ceil(dataCount / defaultRowsPerPage);
  return (
    <Box
      className={"flex_between"}
      mt={2}
      bgcolor={"white"}
      border={"1px solid"}
      borderColor={"rgba(224, 224, 224, 1)"}
      py={1}
      px={2}
      width={"100%"}
      sx={sx}
    >
      <Typography variant="h">
        Total {name}: {dataCount}
      </Typography>
      <Pagination
        count={count}
        color={color}
        onChange={handleChange}
        page={page}
      />
    </Box>
  );
};

