  protected override void OnModelCreating(ModelBuilder modelBuilder)
  {
    //modelBuilder.ApplyConfiguration(new ProductConfiguration());

    base.OnModelCreating(modelBuilder);
    modelBuilder.ApplyConfigurationsFromAssembly(Assembly.GetExecutingAssembly());
  }
  protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
  {
    optionsBuilder.EnableSensitiveDataLogging();
  }
  public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = new CancellationToken())
  {
    int result = await base.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

    // ignore events if no dispatcher provided
    if (_dispatcher == null) return result;

    // dispatch events only if save was successful
    var entitiesWithEvents = ChangeTracker.Entries<EntityBase>()
        .Select(e => e.Entity)
        .Where(e => e.DomainEvents.Any())
        .ToArray();

    await _dispatcher.DispatchAndClearEvents(entitiesWithEvents);

    return result;
  }

  public override int SaveChanges()
  {
    return SaveChangesAsync().GetAwaiter().GetResult();
  }
}

﻿using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Shipra.Backend.API.Core.CarrierAggregate;
using Shipra.Backend.API.Core.ClientAggregate;
using Shipra.Backend.API.Core.EmployeeAggregate;

namespace Shipra.Backend.API.Infrastructure.Data.Config;
public class ActiveCarrierConfiguration : IEntityTypeConfiguration<ActiveCarrier>
{
  public void Configure(EntityTypeBuilder<ActiveCarrier> builder)
  {
    builder.HasKey(e => e.ActiveCarrierId);
    builder.ToTable("ActiveCarrier");
    #region convrsion
    builder.Property(e => e.ClientId).HasConversion(uuid => uuid!.Value, value => new ClientId(value));
    builder.Property(e => e.CreatedBy).HasConversion(uuid => uuid!.Value, value => new EmployeeId(value));
    builder.Property(e => e.UpdatedBy).HasConversion(uuid => uuid!.Value, value => new EmployeeId(value));
    #endregion
    builder.Property(e => e.IsActiveCarrier)
                .HasDefaultValueSql("((0))");
    builder.Property(e => e.Active)
                .HasDefaultValueSql("((1))");
    builder.Property(e => e.CreatedOn).HasColumnType("datetime");
    builder.Property(e => e.UpdatedOn).HasColumnType("datetime");
  }
}

﻿using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Shipra.Backend.API.Core.CarrierAggregate;
using Shipra.Backend.API.Core.ClientAggregate;

namespace Shipra.Backend.API.Infrastructure.Data.Config;

public class ActiveCarrierPickupLocationConfiguration : IEntityTypeConfiguration<ActiveCarrierPickupLocation>
{
  public void Configure(EntityTypeBuilder<ActiveCarrierPickupLocation> builder)
  {
    builder.ToTable("ActiveCarrierPickupLocation"); 
    #region convrsion
    builder.Property(e => e.ClientId).HasConversion(uuid => uuid!.Value, value => new ClientId(value));
    #endregion

    builder.Property(e => e.AreaName).HasMaxLength(150);
    builder.Property(e => e.BuildingName).HasMaxLength(50);
    builder.Property(e => e.FullAddress).HasMaxLength(200);
    builder.Property(e => e.HouseNo).HasMaxLength(20);
    builder.Property(e => e.Landmark).HasMaxLength(50);
    builder.Property(e => e.Latitude).HasColumnType("decimal(8, 6)");
    builder.Property(e => e.Longitude).HasColumnType("decimal(9, 6)");
    builder.Property(e => e.StreetAddress).HasMaxLength(150);
    builder.Property(e => e.StreetAddress2).HasMaxLength(500);
    builder.Property(e => e.Zip).HasMaxLength(10);
  }
}

﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Shipra.Backend.API.Core.ActivityLogAggregate;
using Shipra.Backend.API.Core.ClientAggregate;
using Shipra.Backend.API.Core.EmployeeAggregate;

namespace Shipra.Backend.API.Infrastructure.Data.Config;
public class ActivityLogConfiguration : IEntityTypeConfiguration<ActivityLog>
{
  public void Configure(EntityTypeBuilder<ActivityLog> builder)
  {
    builder.ToTable("ActivityLog");

    #region conversion
    builder.Property(e => e.ActivityLogId).HasConversion(uuid => uuid!.Value, value => new ActivityLogId(value));
    builder.Property(e => e.ClientId).HasConversion(uuid => uuid!.Value, value => new ClientId(value));
    builder.Property(e => e.EmployeeId).HasConversion(uuid => uuid!.Value, value => new EmployeeId(value));
    #endregion

    builder.Property(e => e.ActivityLogId).ValueGeneratedNever();
    builder.Property(e => e.Aggregate).HasMaxLength(150);
    builder.Property(e => e.CreateOn).HasColumnType("datetime");
    builder.Property(e => e.Request).HasColumnType("text");
    builder.Property(e => e.Response).HasColumnType("text");
  }
}

