                                    INNER JOIN
                                    (SELECT DeliveryNoteId, NoteNo FROM dbo.DeliveryNote) AS dn
                                        ON dn.DeliveryNoteId = SubQuery.DeliveryNoteId ORDER BY dn.NoteNo DESC";

