                            ( emp.EmployeeName in (select value from STRING_SPLIT(@search,',')))
                             OR
                            ( dn.NoteNo in (select value from STRING_SPLIT(@search,',')))
                            OR
                            ( ec.ExpenceName in (select value from STRING_SPLIT(@search,','))) ";
