                      WHERE srgs.ServiceRateGroupId = @serviceRateGroupId
                      ORDER BY srgs.ServiceRateGroupSlabId ";

      dynamicParams.Add("@serviceRateGroupId", serviceRateGroupId);
      dynamicParams.Add("@saleChannelConfigId", saleChannelConfigId);

