  private async Task<List<AmazonOrder>?> GetAmazonOrdersAsync(string baseUrl, string accessToken, DateTime createdFrom, string? marketplaceId)
  {
    try
    {
      using (var client = new HttpClient())
      {
        // Strip trailing slashes and normalize baseUrl path
        var normalizedBaseUrl = baseUrl.TrimEnd('/');
        var formattedCreatedFrom = "2024-12-25T00:00:00Z";//createdFrom.ToString("yyyy-MM-ddTHH:mm:ssZ");
        var requestUri = $"{normalizedBaseUrl}/orders/2026-01-01/orders?createdAfter={formattedCreatedFrom}&marketplaceIds={marketplaceId}&includedData=BUYER,RECIPIENT,PROCEEDS,EXPENSE,PROMOTION,CANCELLATION,FULFILLMENT,PACKAGES";

        client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", accessToken);
        client.DefaultRequestHeaders.Add("x-amz-access-token", accessToken);

        var response = await client.GetAsync(requestUri);
        var responseContentR = await response.Content.ReadAsStringAsync();
        if (response.IsSuccessStatusCode)
        {
          var responseContent = await response.Content.ReadAsStringAsync();
          var ordersResponse = JsonConvert.DeserializeObject<AmazonOrderListResponse>(responseContent);
