          throw new ShipraApplicationException(HttpStatusCode.ExpectationFailed, $"Error fetching Amazon orders: {response.StatusCode} - {response.ReasonPhrase}");
        }
      }
    }
    catch (Exception)
    {
      throw;
    }
  }

  private (List<CreateUploadOrderResponseModel> Shipments, List<AmazonOrderError> Errors) MapAmazonToShipraOrders(List<AmazonOrder> amazonOrders,List<Country>? countries,List<Core.CountryAggregate.City> cities,List<Province> provinces,List<State> states,List<Area> areas,List<PinCode> pinCodes,Store? oStore,SaleChannelConfig oSaleChannelConfig,int? orderTypeId,IEnumerable<dynamic>? castedProductList = null)
  {
    var shipments = new List<CreateUploadOrderResponseModel>();
    var errors = new List<AmazonOrderError>();

    int row = 0;
    foreach (var x in amazonOrders)
    {
      row++;
      var deliveryAddress = x.Recipient?.DeliveryAddress;
      var obj = new CreateUploadOrderResponseModel
      {
        StoreId = oStore?.StoreId ?? 0,
        OrderTypeId = orderTypeId,
        OrderDate = x.CreatedTime ?? DateTime.UtcNow,
        Description = $"Amazon Order {x.OrderId}",
        Remarks = string.Empty,
        Amount = x.Proceeds?.GrandTotal?.GetAmountDecimal() ?? 0,
        CShippingCharges = 0,
        PaymentStatusId = (int)EnumPaymentStatus.Paid, // Amazon orders are typically pre-paid
        Weight = 0,
        ItemValue = x.Proceeds?.GrandTotal?.GetAmountDecimal() ?? 0,
        OrderRequestVia = (int)EnumOrderRequestVia.Api,
        PaymentMethodId = (int)EnumPaymentMethod.PP, // Pre-paid
        StationId = (int)EnumStationLookup.Dubai,
        Discount = 0,
        VAT = 0,
        SCOrderNo = x.OrderId,
        SCOrderId = x.OrderId,
        SaleChannelConfigId = oSaleChannelConfig.SaleChannelConfigId,
        SaleChannelLookupId = oSaleChannelConfig.SaleChannelLookupId,
        OrderNote = new OrderNoteModel { Note = "" },
        OrderAddress = new OrderAddressResponseModel
        {
          CustomerName = x.Buyer?.BuyerName ?? deliveryAddress?.Name ?? "Amazon Customer",
          Email = x.Buyer?.BuyerEmail ?? string.Empty,
          Mobile1 = deliveryAddress?.Phone ?? string.Empty,
          StreetAddress = deliveryAddress != null ? $"{deliveryAddress.AddressLine1 ?? ""}{(string.IsNullOrEmpty(deliveryAddress.AddressLine2) ? "" : ", " + deliveryAddress.AddressLine2)}" : string.Empty
        },
        OrderItems = new List<OrderItemModel>()
      };

      var error = new AmazonOrderError
      {
        Row = row,
        IsSuccessed = true
      };

      // Country Lookup
      Country? matchedCountry = null;
      if (deliveryAddress != null && !string.IsNullOrEmpty(deliveryAddress.CountryCode))
      {
        matchedCountry = countries?.FirstOrDefault(y => y.MapCountryCode?.Trim().ToLower() == deliveryAddress.CountryCode.Trim().ToLower());
        if (matchedCountry != null)
        {
          obj.OrderAddress.Country = matchedCountry.CountryId;
        }
        else
        {
          error.IsSuccessed = false;
          error.Msg.Add("Invalid Country Code.");
        }
      }
      else
      {
        error.IsSuccessed = false;
        error.Msg.Add("Country Code is missing.");
      }

      // State and City Lookup
      if (deliveryAddress != null && !string.IsNullOrEmpty(deliveryAddress.StateOrRegion) && matchedCountry != null)
      {
        var matchedProvince = provinces.FirstOrDefault(y => y.Name!.Trim().ToLower() == deliveryAddress.StateOrRegion.Trim().ToLower() && matchedCountry.CountryId == y.CountryId);
        var matchedState = matchedProvince == null ? states.FirstOrDefault(y => y.Name!.Trim().ToLower() == deliveryAddress.StateOrRegion.Trim().ToLower() && matchedCountry.CountryId == y.CountryId) : null;

        if (matchedProvince != null)
        {
          obj.OrderAddress.Province = matchedProvince.ProvinceId;

if (matchedCountry != null)
        {
          obj.OrderAddress.Country = matchedCountry.CountryId;
        }
        else
        {
          error.IsSuccessed = false;
          error.Msg.Add("Invalid Country Code.");
        }
      }
      else
      {
        error.IsSuccessed = false;
        error.Msg.Add("Country Code is missing.");
      }

      // State and City Lookup
      if (deliveryAddress != null && !string.IsNullOrEmpty(deliveryAddress.StateOrRegion) && matchedCountry != null)
      {
        var matchedProvince = provinces.FirstOrDefault(y => y.Name!.Trim().ToLower() == deliveryAddress.StateOrRegion.Trim().ToLower() && matchedCountry.CountryId == y.CountryId);
        var matchedState = matchedProvince == null ? states.FirstOrDefault(y => y.Name!.Trim().ToLower() == deliveryAddress.StateOrRegion.Trim().ToLower() && matchedCountry.CountryId == y.CountryId) : null;

        if (matchedProvince != null)
        {
          obj.OrderAddress.Province = matchedProvince.ProvinceId;
          if (!string.IsNullOrEmpty(deliveryAddress.City))
          {
            var oCity = cities.FirstOrDefault(y => y.Code!.Trim().ToLower() == deliveryAddress.City.Trim().ToLower() && matchedProvince.ProvinceId == y.ProvinceId);
            if (oCity != null) obj.OrderAddress.City = oCity.CityId;
          }
        }
        else if (matchedState != null)
        {
          obj.OrderAddress.State = matchedState.StateId;
          if (!string.IsNullOrEmpty(deliveryAddress.City))
          {
            var oCity = cities.FirstOrDefault(y => y.Code!.Trim().ToLower() == deliveryAddress.City.Trim().ToLower() && matchedState.StateId == y.StateId);
            if (oCity != null) obj.OrderAddress.City = oCity.CityId;
          }
        }
        else if (obj.OrderAddress.City == null && !string.IsNullOrEmpty(deliveryAddress.City))
        {
          var oCity = cities.FirstOrDefault(y => y.Name!.Trim().ToLower() == deliveryAddress.City.Trim().ToLower() && matchedCountry.CountryId == y.CountryId);
          if (oCity != null)
          {
            obj.OrderAddress.City = oCity.CityId;
          }
          else
          {
            error.IsSuccessed = false;
            error.Msg.Add("Invalid City.");
          }
        }
      }

      // Phone validation
      if (deliveryAddress != null && !string.IsNullOrEmpty(deliveryAddress.Phone))
      {
        if (deliveryAddress.Phone.Length <= 20)
