            Description = $"SKU: {item.Product?.SellerSKU} - Qty: {item.QuantityOrdered}",
            Remarks = string.Empty,
            Quantity = item.QuantityOrdered,
            Discount = 0
          });
        }
      }
      else if (orderTypeId == (int)EnumOrderType.FullFilable && castedProductList != null)
      {
        foreach (var item in x.OrderItems ?? new List<AmazonOrderItem>())
        {
          var product = castedProductList.FirstOrDefault(p => (string)p.SKU == item.Product?.SellerSKU);
          if (product != null)
          {
            obj.OrderItems.Add(new OrderItemModel
            {
              ProductId = product.ProductId,
              ProductVariantId = product.ProductVariantId,
              Price = item.Product?.Price?.UnitPrice?.GetAmountDecimal() ?? item.Proceeds?.ProceedsTotal?.GetAmountDecimal() ?? 0,

