  private List<AmazonReportProduct> ParseTsvProducts(string tsvText)
  {
    var products = new List<AmazonReportProduct>();
    if (string.IsNullOrEmpty(tsvText)) return products;
    var lines = tsvText.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.RemoveEmptyEntries);
    if (lines.Length <= 1) return products;
    var headers = lines[0].Split('\t').Select(h => h.Trim().ToLower()).ToList();
    for (int i = 1; i < lines.Length; i++)
    {
      var values = lines[i].Split('\t');
      var item = new AmazonReportProduct();
      for (int j = 0; j < headers.Count; j++)
      {
        if (j >= values.Length) break;
        var header = headers[j];
        var val = values[j].Trim();
        if (header == "item-name" || header == "title" || header == "name") item.ItemName = val;
        else if (header == "item-description" || header == "description") item.Description = val;
        else if (header == "seller-sku" || header == "sku") item.SellerSku = val;
        else if (header == "price") { if (decimal.TryParse(val, out decimal price)) item.Price = price; }
        else if (header == "quantity" || header == "qty") { if (int.TryParse(val, out int qty)) item.Quantity = qty; }
        else if (header == "asin1" || header == "asin") item.Asin = val;
        else if (header == "image-url" || header == "main-image-url") item.ImageUrl = val;
      }
      if (!string.IsNullOrEmpty(item.Asin) || !string.IsNullOrEmpty(item.SellerSku))
        products.Add(item);
    }
    return products;
  }
