  {
    int? value = null;

    if (sourceValue != null)
    {
      if (sourceValue is int)
      {
        value = (int)sourceValue;
      }
      else if (!string.IsNullOrWhiteSpace(sourceValue.ToString()))
      {
        value = Convert.ToInt32(sourceValue);
      }
