      if (!string.IsNullOrEmpty(wooCommerceOrderAddress.phone))
      {
        if (wooCommerceOrderAddress.phone.Length <= 20)
        {
          if (country != null)
          {
            var res = Utility.ValidateMobileAndGetNumber(wooCommerceOrderAddress.phone, country!.MapCountryCode!.ToUpper());
