        Directory.CreateDirectory(path);
      } 
      modifiedHtmlContent = modifiedHtmlContent.Replace("{{printDate}}", DateTime.Now.ToString());
      string base64Barcode = _barcodeGenerate.CreateBase64(returnReport.ReturnReportNo!, 500, 100);

