  private string GenerateSaleChannelKey(string saleChannelName)
  {
    var name = saleChannelName.Trim()
                       .Replace(" ", "")
                       .ToLowerInvariant();

    var randomKey = Random.Shared.Next(1000, 9999);

    return $"{name}{randomKey}";
  }
