  : AbstractValidator<CreateBulkStoreWithSalePersonCommand>
{
  public CreateBulkStoreWithSalePersonCommandValidator()
  {
    RuleFor(x => x.List)
      .NotNull() 
      .WithMessage("Request list must contain at least one store.");
  }
