      else
      { 
        serviceResult.CreateError("AlreadyExist", new string[] { $"Tax already exist." });
      }

      return serviceResult;
    }
    catch (Exception ex)
    {
      serviceResult.CreateErrorResponse(ex);
      throw;
    }
  }
}

