using System.Security.Cryptography;
using Shipra.Backend.API.Application.Services.Interfaces;

namespace Shipra.Backend.API.Application.Services.Implementation;

/// <summary>
/// Generates cryptographically secure one-time passwords.
/// </summary>
public class OtpService : IOtpService
{
  /// <summary>
  /// Generates a cryptographically secure 6-digit OTP.
  /// </summary>
  /// <returns>A 6-digit numeric OTP string (e.g., "042917").</returns>
  public string GenerateOtp()
  {
    var otp = RandomNumberGenerator.GetInt32(0, 1000000);
    return otp.ToString("D6");
  }
}

﻿using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Generic;
using Microsoft.AspNetCore.Hosting;
using iText.Kernel.Pdf;
using iText.Html2pdf;
using iText.Kernel.Geom;
using iText.Layout;
using iText.Layout.Element; 
using iText.IO.Font;
using iText.Kernel.Font;
using iText.Kernel.Events;
using iText.Kernel.Pdf.Canvas;
using DocumentFormat.OpenXml.Presentation;

namespace Shipra.Backend.API.Application.Services.Implementation;
public class PdfEventHandler : IEventHandler
{
  private readonly string _footerContent; 

  public PdfEventHandler(string footerContent)
  {
    _footerContent = footerContent; 
  }

  public void HandleEvent(Event currentEvent)
  {
    PdfDocumentEvent docEvent = (PdfDocumentEvent)currentEvent;
    PdfDocument pdfDoc = docEvent.GetDocument();
    PdfPage page = docEvent.GetPage();
    PdfCanvas pdfCanvas = new PdfCanvas(page.NewContentStreamBefore(), page.GetResources(), pdfDoc);
    Rectangle pageSize = page.GetPageSize();

    // Add top border 
    pdfCanvas.MoveTo(pageSize.GetLeft(), pageSize.GetBottom() + 25)
             .LineTo(pageSize.GetRight(), pageSize.GetBottom() + 25)
             .Stroke();

    // Create a font program from a font file
    PdfFont font = PdfFontFactory.CreateFont(@"C:\Windows\Fonts\arialbd.ttf", PdfEncodings.IDENTITY_H);

    // Add footer content
    // Get the width of the footer content
    float textWidth = font.GetWidth(_footerContent, 12);

    // Set padding
    float padding = 5; // Adjust padding value as needed

    // Calculate the x-coordinate with padding
    float xCoordinate = pageSize.GetRight() - textWidth - padding;

    //Add footer content aligned to the right
    pdfCanvas.BeginText()
             .SetFontAndSize(font, 10)
             .MoveText(xCoordinate, pageSize.GetBottom() + 7)
             .ShowText(_footerContent)
             .EndText();

    pdfCanvas.Release();
  }
}

﻿using Shipra.Backend.API.Core.ClientAggregate;
using Shipra.Backend.API.Core.Enum;
using Shipra.Backend.API.Core.Interfaces;
using Shipra.Backend.API.Core.Models;
using Shipra.Backend.API.Core.SMSProcessAggregate;

namespace Shipra.Backend.API.Application.Services.Interfaces;
public class SmsService : ISmsService
{
  private readonly ISmsProviderFactory smsProviderFactory;
  private readonly ISMSProcessRepository _smsProcessRepository;

  public SmsService(ISMSProcessRepository sMSProcessRepository, ISmsProviderFactory smsProviderFactory)
  {
    _smsProcessRepository = sMSProcessRepository;
    this.smsProviderFactory = smsProviderFactory;
  }

  public async Task SendSms(Message message, ClientId clientId, int? sMSActivateId = 0)
  {
    try
    {
      var allClientMessages = await _smsProcessRepository.GetAllSmsActivated(clientId!);
      if (allClientMessages?.Count > 0)
      {
        SMSActivate? oSmsActivated = allClientMessages!.FirstOrDefault(x => x.IsDefault == true); ;
        if (sMSActivateId > 0)
        {
          oSmsActivated = allClientMessages!.FirstOrDefault(x => x.SMSActivateId == sMSActivateId);
        } 
        if (oSmsActivated is not null)
        { 
          EnumSMSLookup providerType = (EnumSMSLookup)Enum.ToObject(typeof(EnumSMSLookup), oSmsActivated.SMSLookupId.GetValueOrDefault());

          ISmsProvider smsProvider = smsProviderFactory.CreateSmsProvider(providerType);
          await smsProvider.Send(message, oSmsActivated.Config!);
        }
      }
    }
    catch (Exception ex)
    {
      _ = ex.Message;
      throw;
    }

  }
}

